const fs = require('fs');

async function main() {
  const target = await (await fetch('http://localhost:9333/json/new?file:///tmp/svgbench.ngpES4/output.svg', {method: 'PUT'})).json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let id = 0;
  const pending = new Map();
  ws.onmessage = (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) {
      const {resolve, reject} = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) reject(new Error(JSON.stringify(msg.error)));
      else resolve(msg.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const mid = ++id;
    pending.set(mid, {resolve, reject});
    ws.send(JSON.stringify({id: mid, method, params}));
  });
  await new Promise(r => ws.onopen = r);
  await send('Page.enable');
  await send('Runtime.enable');
  await new Promise(r => setTimeout(r, 1200));
  const evalExpr = async (expression) => (await send('Runtime.evaluate', {expression, returnByValue: true})).result?.value;
  console.log('currentTime', await evalExpr('document.documentElement.getCurrentTime()'));
  await evalExpr('document.documentElement.pauseAnimations()');
  for (const t of [0, 1, 2, 4]) {
    await evalExpr(`document.documentElement.setCurrentTime(${t})`);
    await new Promise(r => setTimeout(r, 250));
    const shot = await send('Page.captureScreenshot', {format: 'png'});
    fs.writeFileSync(`/tmp/svgbench.ngpES4/cdp_${t}.png`, Buffer.from(shot.data, 'base64'));
    console.log('captured', t);
  }
  ws.close();
  process.exit(0);
}
main().catch(e => { console.error(e); process.exit(1); });

